INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8-u1-present-perfect-1', '现在完成时(一)', 'A2', 8, '现在完成时=have/has+过去分词,表示过去发生、对现在有影响的动作,或到现在为止的经历。第三人称单数用 has,其余用 have。规则动词过去分词加 -ed(finished, cleaned);不规则动词需单独记(be→been, go→gone, see→seen, do→done, come→come)。常与 already(已经,肯定句)、yet(还,疑问/否定句末)、just(刚刚)、ever(曾经,疑问句)、never(从未)、before(以前)连用。', 1, 'wy8A', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8-u2-present-perfect-2', '现在完成时(二)', 'A2', 8, '现在完成时表示"持续到现在"时,常与 since 和 for 连用:since+过去的时间点(since 2019, since last year),for+一段时间(for two years, for a long time)。提问持续多久用 How long...?。have/has been to 表示"去过某地(已回来)";have/has gone to 表示"去了某地(还没回来)"。这些都用 have/has+过去分词,不用被动。', 2, 'wy8A', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8-u3-infinitive-gerund-object', '不定式与动名词作宾语', 'A2', 8, '有些动词后接动词不定式(to do)作宾语:want/hope/decide/plan/agree/learn/offer/promise/would like + to do。有些动词后接动名词(doing)作宾语:enjoy/finish/mind/keep/practise/avoid/miss/give up + doing。like/love/hate/start/begin/continue 后接 to do 或 doing 均可。选词时先判断该动词要求哪种形式。', 3, 'wy8A', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='verb' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8-u4-infinitive-object-complement', '不定式作宾语补足语', 'A2', 8, '"动词+宾语+不定式"结构中,不定式作宾语补足语:ask/tell/want/would like/teach/help + sb + to do sth(叫/让某人做某事)。但 make(使)、let(让)、help 后可接不带 to 的不定式(原形):make sb do, let sb do, help sb (to) do。注意这些不是宾语从句,不用 that。', 4, 'wy8A', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='verb' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8-u5-infinitive-purpose', '不定式表目的', 'A2', 8, '动词不定式 to do 可作目的状语,表示"为了做某事",回答 Why 提问。可用 to do,也可用 in order to do 或 so as to do,语气更正式。不定式表目的常放在句末或句首(In order to..., ...)。注意:表目的用不定式,不用 for+doing。', 5, 'wy8A', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='verb' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy8-u6-past-continuous', '过去进行时', 'A2', 8, '过去进行时=was/were+现在分词(doing),表示过去某一时刻正在进行的动作。主语单数用 was,复数/you 用 were。常与 when(当…时,后接一般过去时,表示打断)和 while(在…期间,后接过去进行时)连用:When the phone rang, I was cooking. / While they were playing, it began to rain。否定加 not(wasn''t/weren''t)。', 6, 'wy8A', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'I have already ____ my homework.', 'finish', 'finishing', 'finishes', 'finished', 'D', 'have+过去分词;finish→finished。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'She has ____ to Shanghai twice.', 'being', 'is', 'been', 'be', 'C', 'has been to 表示"去过";be 的过去分词是 been。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'They have already ____ the new film.', 'seen', 'see', 'seeing', 'sees', 'A', 'see 的过去分词是 seen。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'He has ____ his keys, so he can''t open the door.', 'lose', 'lost', 'loses', 'losing', 'B', 'lose 的过去分词是 lost。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'We have ____ this book before.', 'to read', 'reading', 'read', 'reads', 'C', 'read 的过去分词与原形同形 read。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'My sister has just ____ her room.', 'cleaned', 'clean', 'cleans', 'cleaning', 'A', 'just+过去分词;clean→cleaned。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'I have never ____ such a big dog.', 'see', 'seen', 'seeing', 'saw', 'B', 'never+过去分词 seen;saw 是过去式不能跟 have。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'Tom has just ____ home.', 'comes', 'coming', 'came', 'come', 'D', 'come 的过去分词是 come;came 是过去式,不能跟 has。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'The students have ____ their homework to the teacher.', 'gives', 'give', 'given', 'giving', 'C', 'give 的过去分词是 given。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'She has ____ finished, so she is free now.', 'never', 'ever', 'yet', 'already', 'D', 'already 用于肯定句,表"已经"。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'Have you cleaned the classroom ____?', 'yet', 'ever', 'just', 'already', 'A', 'yet 用于疑问句末,表"还(没)"。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'He has ____ eaten lunch, so he isn''t hungry.', 'yet', 'already', 'ever', 'never', 'B', '肯定句用 already。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), '____ your father ever ____ this song before?', 'Has; heard', 'Has; hear', 'Have; hears', 'Have; heard', 'A', '主语 father 单数用 Has;ever+过去分词 heard。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'My parents have ____ done the housework.', 'never', 'already', 'yet', ' nothing', 'B', '肯定句"已经"用 already。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'I ____ my grandparents. I miss them a lot.', 'don''t see', 'didn''t see', 'haven''t seen', 'am not seeing', 'C', '表"一直没见到"的经历用现在完成时否定 haven''t seen。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), '— Have you finished the work? — Yes, I ____.', 'do', 'am', 'did', 'have', 'D', '现在完成时一般疑问的肯定简答用 have。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'She has ____ made the same mistake before.', 'ever', 'yet', 'never', 'already', 'C', '陈述"从未"用 never。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'Look! The train has already ____.', 'left', 'leave', 'leaves', 'leaving', 'A', 'leave 的过去分词是 left。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'We have ____ our bikes, so we have to walk now.', 'break', 'breaking', 'breaks', 'broken', 'D', 'break 的过去分词是 broken。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u1-present-perfect-1'), 'He has ____ up early and ____ the room already.', 'get; clean', 'got; cleaned', 'got; clean', 'get; cleaned', 'B', '两个动词都用过去分词:get→got,clean→cleaned。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'He has lived in this city ____ 2019.', 'since', 'for', 'at', 'in', 'A', 'since+过去的时间点 2019。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'They have studied English ____ three years.', 'in', 'for', 'from', 'since', 'B', 'for+一段时间 three years。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'My grandpa has worked here ____ a long time.', 'from', 'during', 'since', 'for', 'D', 'for+一段时间 a long time。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'We have known each other ____ we were children.', 'when', 'for', 'since', 'while', 'C', 'since+过去时间状语(引导时间起点)。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'She has been ill ____ last Friday.', 'on', 'since', 'at', 'for', 'B', 'since+过去时间点 last Friday。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), '____ have you had this bike?', 'How many', 'How much', 'How often', 'How long', 'D', '提问"持续多久"用 How long。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'Mr Green has taught in our school ____ ten years.', 'for', 'since', 'ago', 'before', 'A', 'for+时间段 ten years。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'Lily has gone to the library. She isn''t here now.', 'going', 'went', 'gone', 'been', 'C', 'has gone to 表"去了还没回";此处她不在。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'My aunt has ____ to Japan. She is back home now.', 'being', 'been', 'went', 'gone', 'B', '回来了→has been to。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'They have been good friends ____ 2015.', 'from', 'in', 'since', 'for', 'C', 'since+年份 2015。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'How long ____ your father ____ this car?', 'have; had', 'has; have', 'have; has', 'has; had', 'D', '主语 father 单数用 has;have 的过去分词 had。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'I haven''t seen him ____ last month.', 'since', 'yet', 'before', 'for', 'A', 'since+过去时间点 last month。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'She has kept the secret ____ many years.', 'from', 'during', 'for', 'since', 'C', 'for+时间段 many years。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), '— How long have you been in China? — ____ 2020.', 'Since', 'From', 'For', 'In', 'A', '回答时间点用 Since。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'We have been in this school ____ two years, and we love it.', 'since', 'for', 'before', 'ago', 'B', 'for+时间段 two years。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'My brother has gone to the shop, so he ____ at home now.', 'doesn''t', 'wasn''t', 'hasn''t', 'isn''t', 'D', 'has gone(还没回)→现在不在家 isn''t。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'She has learnt the piano ____ she was six.', 'for', 'since', 'during', 'when', 'B', 'since+过去时间状语从句(时间起点)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'The Greens have known my family ____ a long time.', 'from', 'since', 'in', 'for', 'D', 'for+一段时间。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'How long ____ they ____ each other? — For about ten years.', 'have; known', 'has; known', 'have; know', 'has; know', 'A', '主语 they 用 have;know 的过去分词 known。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u2-present-perfect-2'), 'My father has worked in Beijing ____ 2016, and my mother has stayed there ____ six years.', 'for; for', 'for; since', 'since; for', 'since; since', 'C', '2016 是时间点用 since;six years 是时间段用 for。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u3-infinitive-gerund-object'), 'I enjoy ____ football after school.', 'plays', 'to play', 'playing', 'play', 'C', 'enjoy 后接动名词 doing。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u3-infinitive-gerund-object'), 'She wants ____ a doctor in the future.', 'be', 'is', 'being', 'to be', 'D', 'want 后接不定式 to do。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u3-infinitive-gerund-object'), 'He finished ____ the book last night.', 'reads', 'reading', 'read', 'to read', 'B', 'finish 后接动名词 doing。', 1, 3, 'mcq');
