INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u5-infinitive-purpose'), '____ pass the exam, she has studied very hard.', 'So that', 'In order for', 'In order to', 'For to', 'C', 'In order to do 置于句首表目的。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u5-infinitive-purpose'), 'He practises running every day ____ join the school team.', 'to', 'with', 'by', 'for', 'A', 'to do 表目的。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u5-infinitive-purpose'), 'My father drives carefully ____ keep everyone safe.', 'by', 'to', 'for', 'of', 'B', 'to do 表目的。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u5-infinitive-purpose'), 'We got up very early ____ climb the mountain and ____ see the sun rise.', 'to; for', 'for; to', 'to; to', 'for; for', 'C', '两处都用 to do 表目的。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u5-infinitive-purpose'), 'She stayed up late ____ finish her work so as ____ hand it in on time.', 'for; for', 'for; to', 'to; for', 'to; to', 'D', 'to do 表目的;so as to do 也表目的,都用 to。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'I ____ TV when you called me.', 'watch', 'watched', 'was watching', 'am watching', 'C', '过去某刻正在进行,用 was+doing。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'They ____ football at four o''clock yesterday.', 'were playing', 'played', 'are playing', 'play', 'A', '复数主语 they 用 were+doing。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'She ____ her homework when I came in.', 'did', 'is doing', 'does', 'was doing', 'D', 'was+doing 表当时正在进行。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'We ____ dinner at seven o''clock last night.', 'are having', 'were having', 'had', 'have', 'B', '过去某刻正在进行,were+having。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'What ____ you ____ at nine last night?', 'were; doing', 'are; doing', 'was; doing', 'did; do', 'A', '主语 you 用 were;过去进行时 were+doing。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'While the teacher ____, a student came in.', 'speaks', 'is speaking', 'was speaking', 'spoke', 'C', 'while+过去进行时 was speaking。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'When the rain ____, we were playing outside.', 'starts', 'was starting', 'has started', 'started', 'D', 'when 引导的动作用一般过去时 started 表打断。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'My father ____ a book while my mother was cooking.', 'is reading', 'was reading', 'reads', 'read', 'B', 'while 分句用过去进行时 was reading。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'The children ____ not sleeping when their parents got home.', 'were', 'are', 'was', 'did', 'A', '复数主语过去进行时否定 were not。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'At this time yesterday, I ____ on the beach.', 'lay', 'am lying', 'lie', 'was lying', 'D', '过去某刻正在进行 was lying。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'While we ____ about the film, the phone rang.', 'talk', 'are talking', 'were talking', 'talked', 'C', 'while+过去进行时 were talking。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'She ____ a shower when the phone rang.', 'takes', 'was taking', 'is taking', 'took', 'B', 'was taking 表当时正在进行。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'They ____ in the park when it began to rain.', 'walked', 'are walking', 'were walking', 'walk', 'C', '过去进行时 were walking。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'What ____ he ____ when you saw him?', 'were; doing', 'did; do', 'is; doing', 'was; doing', 'D', '主语 he 单数用 was;was+doing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'I ____ my bike to school when I met my teacher.', 'rode', 'was riding', 'ride', 'am riding', 'B', 'was riding 表当时正在进行。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'The students ____ quietly while the teacher wrote the new words.', 'were reading', 'read', 'are reading', 'reads', 'A', 'while 分句用过去进行时 were reading。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'It ____ hard when we left the house this morning.', 'rains', 'was raining', 'rained', 'is raining', 'B', '过去某刻正在进行 was raining。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'He wasn''t ____ when the rain started.', 'drove', 'drive', 'driving', 'drives', 'C', '过去进行时否定 wasn''t driving。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'While my sister ____ the room, I ____ the flowers.', 'cleaned; watered', 'was cleaning; watered', 'cleaned; was watering', 'was cleaning; was watering', 'D', '两个动作同时进行,都用过去进行时。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy8A' AND code='wy8-u6-past-continuous'), 'When I ____ into the classroom, the students ____ a song.', 'walked; were singing', 'walked; sang', 'was walking; sang', 'was walking; were singing', 'A', 'walk 是短暂动作用一般过去时 walked;sing 正在进行用 were singing。', 3, 20, 'mcq');
